<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';
import {VueFlow} from '@vue-flow/core';
import {Background} from '@vue-flow/background';
import {Controls} from '@vue-flow/controls';
import {api} from '../api';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import DraftStatus from './DraftStatus.vue';
import {emptyConfiguration,configGraph,configOffset,configByteOffset,sourceDeclaration,scalarProperties,type ConfigProject,type Compilation,type Artifact,type ConfigReport,type ConfigPackage,type Completion,type Span} from '../configuration';
const emit=defineEmits<{catalog:[];system:[any]}>();
const project=ref<ConfigProject>(emptyConfiguration()),report=ref<ConfigReport|null>(null),release=ref<ConfigPackage|null>(null);
const recovery=useWorkspaceDraft('configuration-project-v1',{project,report,release});
const busy=ref(''),error=ref(''),notice=ref('');useActionFeedback('Configuration language',busy,notice,error);
const view=ref('Source'),file=ref('main.lce'),search=ref(''),selected=ref(''),node=ref(''),libraryOpen=ref(true),inspectorOpen=ref(true);
const compiled=ref<Compilation|null>(null),compiledStamp=ref(''),reportStamp=ref(''),completions=ref<Completion[]>([]),renameTo=ref(''),newFile=ref('');
const packageID=ref('local.configuration'),packageVersion=ref('1.0.0'),comparison=ref<any>(null),releases=ref<{id:string;version:string;digest:string}[]>([]);
const editor=ref<HTMLTextAreaElement|null>(null),upload=ref<HTMLInputElement|null>(null),previousUpload=ref<HTMLInputElement|null>(null);
const stamp=()=>JSON.stringify(project.value);const current=computed(()=>compiledStamp.value===stamp()&&!!compiled.value?.valid);
const artifact=computed(()=>current.value?compiled.value?.artifacts.find(a=>a.symbol===selected.value):undefined);
const stage=ref(''),manualLayout=ref(false);
const stages=computed(()=>artifact.value?.kind==='workflow'?[...new Set((artifact.value.body.nodes||[]).map((n:any)=>(n.stage||'').split('/')[0]))].filter(Boolean) as string[]:[]);
const graph=computed(()=>artifact.value?configGraph(artifact.value,stage.value,manualLayout.value):{nodes:[],edges:[]});
const chosen=computed(()=>graph.value.nodes.find(n=>n.id===node.value));
const properties=computed(()=>artifact.value?scalarProperties(chosen.value?.data.value||artifact.value.body):[]);
const declarations=computed(()=>compiled.value?.documents.find(d=>d.file===file.value)?.declarations||[]);
const files=computed(()=>Object.keys(project.value.files).sort().filter(f=>f.toLowerCase().includes(search.value.toLowerCase())));
const source=computed({get:()=>project.value.files[file.value]||'',set:(value:string)=>{delete project.value.lock;project.value.files[file.value]=value;}});
watch(()=>Object.keys(project.value.files).join('|'),()=>{if(!(file.value in project.value.files))file.value=project.value.entry;});
watch(()=>stamp(),()=>{notice.value='';completions.value=[];});
async function action(label:string,fn:()=>Promise<unknown>){if(busy.value)return;busy.value=label;error.value='';notice.value='';try{await recovery.ready;await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
async function check(){const snapshot=stamp();const result=await api<Compilation>('/configuration/compile','POST',{project:JSON.parse(snapshot)});if(snapshot!==stamp()){notice.value='Source changed during compilation. Compile the current draft.';return false};compiled.value=result;compiledStamp.value=snapshot;if(!result.valid){notice.value=`${result.diagnostics.length} diagnostics. Select one to fix its source.`;return false};if(!result.artifacts.some(a=>a.symbol===selected.value))selected.value=result.artifacts[0]?.symbol||'';notice.value=`${result.artifacts.length} artifacts · ${result.experiments.length} experiments`;return true;}
async function loadExample(){await action('Loading inspection project',async()=>{project.value=await api<ConfigProject>('/configuration/example');file.value=project.value.entry;report.value=null;release.value=null;view.value='Source';await check();});}
async function run(){await action('Running all experiments',async()=>{if(!await check())return;const snapshot=stamp();const r=await api<ConfigReport>('/configuration/run','POST',{project:JSON.parse(snapshot)});report.value=r;reportStamp.value=snapshot;view.value='Testbench';notice.value=r.passed?`${r.cases.length} experiments passed`:'Some experiments failed. Inspect the independent expectations below.';});}
async function transform(kind:string,extra:Record<string,unknown>={}){if(!current.value&&!await check())return;const snapshot=stamp();const r=await api<{project:ConfigProject;compilation:Compilation}>('/configuration/'+kind,'POST',{project:JSON.parse(snapshot),expectedHash:compiled.value!.sourceHash,file:file.value,...extra});if(snapshot!==stamp()){notice.value='The draft changed while preparing this edit. Your newer edits were kept.';return};const prior=artifact.value;project.value=r.project;compiled.value=r.compilation;compiledStamp.value=stamp();if(prior){selected.value=r.compilation.artifacts.find(a=>a.kind===prior.kind&&a.id===prior.id&&a.version===prior.version)?.symbol||selected.value;}notice.value=r.compilation.valid?'Source and graph updated together':'Draft updated; fix the highlighted diagnostics before executing.';}
async function patch(path:string,value:unknown){if(!artifact.value)return;const a=artifact.value;await action('Updating configuration property',()=>transform('patch',{file:a.origin.file,declaration:sourceDeclaration(a),path,value}));}
async function moveNode(event:any){if(!artifact.value||!event.node?.data?.path)return;await patch(event.node.data.path+'.position',{x:Math.round(event.node.position.x),y:Math.round(event.node.position.y)});}
function fieldValue(event:Event,type:string){const e=event.target as HTMLInputElement;return type==='boolean'?e.checked:type==='number'?(e.value===''?null:Number(e.value)):e.value;}
function fieldPath(path:string){return chosen.value?chosen.value.data.path+'.'+path:path;}
async function go(span:Span){file.value=span.file;view.value='Source';await nextTick();const text=project.value.files[span.file]||'';editor.value?.focus();editor.value?.setSelectionRange(configOffset(text,span.start),configOffset(text,span.end));}
async function definition(){await action('Opening symbol definition',async()=>{const span=await api<Span>('/configuration/definition','POST',{project:project.value,file:file.value,offset:configByteOffset(source.value,editor.value?.selectionStart||0)});await go(span);});}
async function complete(){await action('Loading typed suggestions',async()=>{completions.value=await api<Completion[]>('/configuration/complete','POST',{project:project.value,file:file.value,declaration:artifact.value?.origin.file===file.value?sourceDeclaration(artifact.value):'',path:''});});}
function insert(text:string){const el=editor.value;const start=el?.selectionStart??source.value.length,end=el?.selectionEnd??start;source.value=source.value.slice(0,start)+text+source.value.slice(end);void nextTick(()=>{el?.focus();el?.setSelectionRange(start+text.length,start+text.length)});}
function addFile(){let name=newFile.value.trim();if(!/^[a-zA-Z0-9_/-]+\.lce$/.test(name)||name.includes('..')||name.startsWith('/')||project.value.files[name]){error.value='Use a new relative .lce filename.';return};delete project.value.lock;project.value.files[name]=`language "1.0";\nmodule "local.${name.replace(/[^a-zA-Z0-9]/g,'_')}" version "1.0.0";\n`;file.value=name;newFile.value='';view.value='Source';notice.value='Module created. Import it from the entry file to include its declarations.';}
function download(name:string,value:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
async function importFile(event:Event,compare=false){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]),f=files[0];input.value='';if(!f)return;await action('Importing configuration',async()=>{if(files.reduce((n,f)=>n+f.size,0)>32*1024*1024)throw Error('Import exceeds 32 MiB');const text=await f.text();if(compare){if(!release.value)throw Error('Build or open a package first');comparison.value=await api('/configuration/compare','POST',{previous:JSON.parse(text),package:release.value});view.value='Packages';return};if(f.name.endsWith('.lce')){if(/^\s*(?:--[^\n]*\n\s*)*language\s+"1\.0"/i.test(text)){const sources:Record<string,string>={};for(const module of files){if(!module.name.endsWith('.lce')||sources[module.name])throw Error('Select uniquely named .lce modules together.');sources[module.name]=await module.text();}project.value={language:'1.0',entry:sources['main.lce']?'main.lce':f.name,files:sources};}else{if(files.length!==1)throw Error('Migrate one legacy component at a time.');project.value=await api<ConfigProject>('/configuration/migrate','POST',{source:text});}release.value=null;report.value=null;}else{const data=JSON.parse(text);if(data.project&&data.digest){await api('/configuration/verify','POST',{package:data});release.value=data;project.value=data.project;report.value=data.report||null;reportStamp.value=stamp();}else{const check=await api<Compilation>('/configuration/compile','POST',{project:data});if(!check.valid)throw Error(check.diagnostics.map(d=>`${d.file}:${d.line} ${d.message}`).join('\n'));project.value=data;release.value=null;report.value=null;}}file.value=project.value.entry;await check();});}
async function pack(){await action('Building portable package',async()=>{if(!await check())return;const snapshot=stamp();const p=await api<ConfigPackage>('/configuration/pack','POST',{project:JSON.parse(snapshot),id:packageID.value,version:packageVersion.value,test:compiled.value!.experiments.length>0});release.value=p;report.value=p.report||null;reportStamp.value=snapshot;view.value='Packages';notice.value='Package contains source, exact locks, compiled artifacts and test evidence.';});}
async function install(){if(!release.value)return;await action('Installing immutable package',async()=>{const r=await api<{installed:number;existing:number}>('/configuration/install','POST',{package:release.value});emit('catalog');notice.value=`Installed ${r.installed} artifacts; ${r.existing} exact versions already present. Package saved to PostgreSQL.`;await listReleases();});}
async function listReleases(){releases.value=await api('/configuration/packages');}
async function openRelease(id:string,version:string){await action('Opening installed package',async()=>{const p=await api<ConfigPackage>(`/configuration/package?id=${encodeURIComponent(id)}&version=${encodeURIComponent(version)}`);release.value=p;project.value=p.project;report.value=p.report||null;file.value=project.value.entry;reportStamp.value=stamp();await check();});}
async function replay(){if(!release.value)return;await action('Reproducing packaged evidence',async()=>{const r=await api<ConfigReport>('/configuration/replay','POST',{package:release.value});report.value=r;view.value='Testbench';notice.value='Fresh execution exactly matches the packaged evidence.';});}
function selectNode(n:any){if(n.data?.stage!==undefined){stage.value=n.data.stage||'*';node.value='';}else node.value=n.id;}
function openSystem(a:Artifact){emit('system',JSON.parse(JSON.stringify(a.body)));}
function choose(a:Artifact){selected.value=a.symbol;node.value='';stage.value='';file.value=a.origin.file;}
</script>
<template>
<section class="configuration-studio" :aria-busy="!!busy" :inert="recovery.status.value==='loading'">
 <div class="configuration-toolbar"><strong>Configuration Language 1.0</strong><button :disabled="!!busy" @click="loadExample">Inspection example</button><button :disabled="!!busy" @click="upload?.click()">Import / migrate</button><button @click="download('configuration-project.json',project)">Export source</button><button :disabled="!!busy" @click="action('Compiling configuration',check)">Compile</button><button :disabled="!!busy" @click="run">Run testbench</button><button :disabled="!!busy" @click="pack">Build package</button><button :aria-expanded="libraryOpen" @click="libraryOpen=!libraryOpen">{{libraryOpen?'Hide':'Show'}} library</button><button :aria-expanded="inspectorOpen" @click="inspectorOpen=!inspectorOpen">{{inspectorOpen?'Hide':'Show'}} inspector</button></div>
 <DraftStatus :draft="recovery"/>
 <p v-if="busy||notice" role="status">{{busy||notice}}</p><p v-if="error" role="alert" class="config-error">{{error}}</p>
 <nav class="config-views" aria-label="Configuration views"><button v-for="v in ['Source','Canvas','Testbench','Packages']" :key="v" :aria-current="view===v?'page':undefined" @click="view=v">{{v}}</button></nav>
 <div class="configuration-layout" :class="{'no-library':!libraryOpen}">
  <aside v-if="libraryOpen" class="configuration-library"><label>Files and artifacts<input v-model="search" placeholder="Search files"/></label><button v-for="f in files" :key="f" :aria-current="f===file?'page':undefined" @click="file=f;view='Source'">{{f}}{{f===project.entry?' · entry':''}}</button><div class="add-file"><input v-model="newFile" aria-label="New module filename" placeholder="module.lce"/><button :disabled="!!busy" @click="addFile">Add file</button></div><details v-if="current" open><summary>Compiled artifacts ({{compiled?.artifacts.length}})</summary><template v-for="kind in ['definition','behavior','data','state','messages','workflow','system','timing']" :key="kind"><h4 v-if="compiled?.artifacts.some(a=>a.kind===kind)">{{kind}}</h4><button v-for="a in compiled?.artifacts.filter(a=>a.kind===kind)" :key="a.symbol" :aria-pressed="selected===a.symbol" @click="choose(a)">{{a.body.name||a.id}}<small>{{a.version}}</small></button></template></details><p v-else>Compile to refresh the artifact library and graph.</p></aside>
  <main class="configuration-main">
   <template v-if="view==='Source'"><div class="source-actions"><strong>{{file}}</strong><button :disabled="!!busy" @click="action('Formatting source',()=>transform('format'))">Format</button><button :disabled="!!busy" @click="definition">Go to definition</button><button :disabled="!!busy" @click="complete">Suggestions</button><select aria-label="Jump to declaration" @change="go(declarations[Number(($event.target as HTMLSelectElement).value)].nameSpan)"><option disabled selected>Declarations</option><option v-for="(d,i) in declarations" :key="d.name" :value="i">{{d.kind}} {{d.name}}</option></select></div><textarea ref="editor" v-model="source" class="configuration-source" aria-label="Configuration source" spellcheck="false" :disabled="!!busy" @keydown.ctrl.space.prevent="complete" @keydown.f12.prevent="definition"/><div v-if="completions.length" class="suggestions"><button v-for="c in completions" :key="c.kind+c.label" @click="insert(c.kind==='field'?c.label+' = ;':c.label)"><strong>{{c.label}}{{c.required?' *':''}}</strong><small>{{c.type||c.kind}}</small></button></div><div class="rename-bar"><select v-model="selected" aria-label="Artifact to rename"><option v-for="a in compiled?.artifacts" :key="a.symbol" :value="a.symbol">{{sourceDeclaration(a)}}</option></select><input v-model="renameTo" aria-label="New symbol name" placeholder="New symbol name"/><button :disabled="!!busy||!artifact||!renameTo" @click="action('Renaming symbol',()=>transform('rename',{file:artifact!.origin.file,declaration:sourceDeclaration(artifact!),name:renameTo}))">Rename symbol safely</button></div><p class="muted">Ctrl+Space: suggestions · F12: definition. Graph edits update this source. Renaming preserves artifact identities and comments.</p></template>
   <template v-else-if="view==='Canvas'"><p v-if="!current">Compile the current source to inspect its graph. Invalid source remains saved as a draft.</p><template v-else-if="artifact"><div class="canvas-heading"><strong>{{artifact.body.name}} · {{artifact.kind}}</strong><button @click="node=''">Artifact properties</button><select v-if="stages.length" v-model="stage" aria-label="Workflow stage" @change="node=''"><option value="">Stage overview</option><option value="*">All steps</option><option v-for="s in stages" :key="s" :value="s">{{s}}</option></select><label v-if="artifact.kind==='workflow'"><input v-model="manualLayout" type="checkbox"/>Manual positions</label><button @click="go(artifact.origin)">Open source</button><button v-if="artifact.kind==='system'" @click="openSystem(artifact)">Open in system design</button></div><div class="config-canvas"><VueFlow :key="artifact.symbol+'-'+compiledStamp" :nodes="graph.nodes" :edges="graph.edges" fit-view-on-init :nodes-connectable="false" @node-click="selectNode($event.node)" @node-drag-stop="moveNode"><Background/><Controls/></VueFlow><p v-if="!graph.nodes.length" class="canvas-empty">No internal nodes. Edit artifact properties or add declarations in source.</p><aside v-if="inspectorOpen" class="config-inspector"><h3>{{chosen?.label||'Artifact properties'}}</h3><label v-for="p in properties" :key="p.path">{{p.path}}<input v-if="p.type==='boolean'" type="checkbox" :checked="p.value as boolean" :disabled="!!busy" @change="patch(fieldPath(p.path),fieldValue($event,p.type))"/><input v-else :type="p.type==='number'?'number':'text'" :value="p.value" :disabled="!!busy" @change="patch(fieldPath(p.path),fieldValue($event,p.type))"/></label><p>Values supplied by shared fixtures are edited at their source. Structural fields are available through typed source suggestions.</p></aside></div></template><p v-else>Add an artifact in source or load the inspection project.</p></template>
   <template v-else-if="view==='Testbench'"><p v-if="!report">Run the testbench to inspect independently specified expectations.</p><template v-else><p :class="report.passed?'config-success':'config-error'">{{report.passed?'Passed':'Failed'}} · {{report.cases.length}} experiments</p><p v-if="!(current&&report.sourceHash===compiled?.sourceHash)&&reportStamp!==stamp()" class="config-error">Evidence belongs to a different source snapshot. Run the current draft again.</p><details v-for="c in report.cases" :key="c.name" :open="!c.passed"><summary>{{c.passed?'✓':'!'}} {{c.name}}</summary><p v-if="c.error" class="config-error">{{c.error}}</p><div class="config-table"><table><thead><tr><th>Expectation</th><th>Expected</th><th>Observed</th><th>Result</th></tr></thead><tbody><tr v-for="a in c.assertions" :key="a.path"><td>{{a.path}}</td><td><code>{{JSON.stringify(a.expected)}}</code></td><td><code>{{a.observed?JSON.stringify(a.actual):'Missing observation'}}</code></td><td>{{a.passed?'Pass':'Fail'}}</td></tr></tbody></table></div><details><summary>Execution trace and state</summary><pre>{{JSON.stringify(c.result,null,2)}}</pre></details></details></template></template>
   <template v-else><div class="package-identity"><label>Package ID<input v-model="packageID"/></label><label>Version<input v-model="packageVersion"/></label><button :disabled="!!busy" @click="pack">Build package</button><button :disabled="!!busy" @click="action('Loading installed packages',listReleases)">Installed packages</button></div><template v-if="release"><h3>{{release.id}} @ {{release.version}}</h3><p v-if="current&&release.project.lock&&JSON.stringify(release.project.files)!==JSON.stringify(project.files)" class="config-error">This package belongs to an earlier source snapshot. Build a new package to include current edits.</p><code class="wrap">{{release.digest}}</code><p>{{release.report?(release.report.passed?'Tests passed':'Tests failed'):'No test evidence'}} · {{release.artifacts.length}} exact artifacts. Systems and deployment models are included in the portable package.</p><div class="package-actions"><button @click="download(release.id+'-'+release.version+'.json',release)">Export package</button><button :disabled="!!busy" @click="install">Install atomically</button><button :disabled="!!busy||!release.report" @click="replay">Replay evidence</button><button :disabled="!!busy" @click="previousUpload?.click()">Compare previous package</button></div></template><details v-if="comparison" open><summary>Compatibility review · {{comparison.compatible?'compatible':'review needed'}}</summary><p v-for="(c,i) in comparison.changes" :key="i">{{c.kind}} · {{c.id}} · {{c.status}}<br/>{{c.detail}}</p></details><button v-for="r in releases" :key="r.id+r.version" class="installed-release" :disabled="!!busy" @click="openRelease(r.id,r.version)">{{r.id}} @ {{r.version}}</button><p class="muted">Installation is one PostgreSQL transaction. Existing versions are immutable. Source packages describe the supported offline engines; live deployment requires the later runtime implementation.</p></template>
   <div v-if="compiled&&!compiled.valid&&compiledStamp===stamp()" class="config-diagnostics" role="alert"><h3>Fix configuration</h3><button v-for="(d,i) in compiled.diagnostics" :key="i" @click="go(d)">{{d.file}}:{{d.line}}:{{d.column}} · {{d.code}} · {{d.path}} — {{d.message}}</button></div>
  </main>
 </div>
 <input ref="upload" type="file" accept=".json,.lce" multiple hidden @change="importFile($event)"/><input ref="previousUpload" type="file" accept=".json" hidden @change="importFile($event,true)"/>
</section>
</template>
<style scoped>
.configuration-studio{min-width:0;max-width:100%}.configuration-toolbar,.config-views,.source-actions,.rename-bar,.package-identity,.package-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0}.configuration-layout{display:grid;grid-template-columns:220px minmax(0,1fr);gap:12px}.configuration-layout.no-library{grid-template-columns:minmax(0,1fr)}.configuration-library{max-height:75vh;overflow:auto;padding:12px;background:#f5f8fa;border-radius:12px;min-width:0}.configuration-library button{display:flex;flex-direction:column;width:100%;text-align:left;overflow-wrap:anywhere;margin:5px 0}.configuration-library label,.configuration-library input{width:100%;box-sizing:border-box}.configuration-main{min-width:0}.configuration-source{box-sizing:border-box;width:100%;min-height:58vh;resize:vertical;font:13px/1.55 ui-monospace,monospace;white-space:pre;overflow:auto;tab-size:2;padding:18px;background:#142832;color:#e7f2ed;border-radius:10px}.config-canvas{height:68vh;min-height:420px;position:relative;overflow:hidden;border:1px solid #d3e1df;border-radius:12px;background:#f9fbfc}.config-inspector{position:absolute;z-index:5;right:12px;top:12px;max-height:90%;overflow:auto;width:min(285px,80%);padding:14px;background:white;border:1px solid #ccd9df;box-shadow:0 8px 25px #203b4620;border-radius:12px}.config-inspector label{display:flex;flex-direction:column;gap:4px;font-size:12px;margin:9px 0;overflow-wrap:anywhere}.config-inspector input{min-width:0;width:100%;box-sizing:border-box}.config-inspector input[type=checkbox]{width:auto;align-self:start}.config-inspector p,.muted{font-size:12px;color:#627781}.canvas-empty{position:absolute;top:20px;left:20px;max-width:45%;pointer-events:none}.canvas-heading{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:10px 0}.suggestions{display:flex;flex-wrap:wrap;gap:6px;max-height:180px;overflow:auto}.suggestions button{display:flex;flex-direction:column;text-align:left}.config-error{color:#a53d32;white-space:pre-wrap}.config-success{color:#168168}.config-diagnostics{border:1px solid #df9f96;padding:12px;margin-top:12px}.config-diagnostics button{text-align:left;display:block;width:100%;margin:5px 0;overflow-wrap:anywhere}.config-table{overflow:auto;max-width:100%}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:10px;border-bottom:1px solid #dce5e7;text-align:left;max-width:300px;overflow-wrap:anywhere}pre{max-height:400px;overflow:auto;background:#eef3f5;padding:12px}details{margin:10px 0}summary{cursor:pointer}.wrap{overflow-wrap:anywhere}.installed-release{display:block;margin:8px 0}button[aria-current=page],button[aria-pressed=true]{color:#086b5b;background:#dff3ed}.package-identity label{display:flex;flex-direction:column;gap:4px}@media(max-width:850px){.configuration-layout{grid-template-columns:minmax(0,1fr)}.configuration-library{max-height:230px}.config-canvas{height:65vh}.configuration-source{min-height:52vh}.configuration-toolbar strong{width:100%}}
</style>
